const users = new UserRepository();

// Repository-backed and promise-based. Resolves to the active user with this
// email, or null if there is none (soft-deleted users don't count).
export async function findUserForLogin(email) {
  const active = await users.findActive();
  return active.find((u) => u.email === email) ?? null;
}

